1	/**
2	 * The screen a map builds itself on.
3	 *
4	 * The same canvas, the same panel and the same keyboard as every other map. What
5	 * is different is where the map comes from: it arrives claim by claim down one
6	 * request, with a reserved rectangle standing wherever the next one will go, and
7	 * every proposal the rules refused listed beside it.
8	 *
9	 * **There is no spinner here, and no moment where a blank screen turns into a
10	 * finished picture.** The growing *is* the loading state.
11	 *
12	 * **This screen does not ask for the map.** The press that opened it did
13	 * (`theRun.ts`), and this watches what that press started. It can be mounted,
14	 * unmounted and mounted again — which React's development mode does on purpose —
15	 * without a second generation being asked for, because there is no code here
16	 * that could ask for one.
17	 */
18	
19	import { useCallback, useEffect, useMemo, useRef, useState, useSyncExternalStore } from "react";
20	import { outlineOf } from "../a11y/sentences";
21	import { AddAClaim } from "../components/AddAClaim";
22	import { type Command, CommandPalette } from "../components/CommandPalette";
23	import { DoneLine } from "../components/DoneLine";
24	import { Inspector } from "../components/Inspector";
25	import { MapFrame } from "../components/MapFrame";
26	import { Outline } from "../components/Outline";
27	import { ReceiptStrip } from "../components/ReceiptStrip";
28	import { RefusalStrip } from "../components/RefusalStrip";
29	import { ReplayBadge, replaySentence } from "../components/ReplayBadge";
30	import { RunStrip } from "../components/RunStrip";
31	import { ShortcutsSheet } from "../components/ShortcutsSheet";
32	import { VerdictCard } from "../components/VerdictCard";
33	import { MapCanvas } from "../graph/Canvas";
34	import { useEveryKey } from "../keyboard/everyKey";
35	import type { MapKeys } from "../keyboard/useMapKeys";
36	import type { Selection } from "../world";
37	import type { Growth, Phase } from "./growth";
38	import { hasStopped } from "./growth";
39	import type { TheRun, WhereItHasGot } from "./theRun";
40	import type { Working } from "./transcript";
41	import { readTranscript } from "./transcript";
42	import "../components/generationDock.css";
43	
44	/**
45	 * Watch a run that is already going.
46	 *
47	 * `useSyncExternalStore` is React's own way of reading something that lives
48	 * outside React and changes on its own, and it is the right one here for a
49	 * reason that matters: subscribing and unsubscribing does nothing to the run.
50	 * A hook that *started* the generation would start two of them in development,
51	 * and *"never retry, a generation that ran twice would spend twice"* would be
52	 * broken on every machine where the app is developed.
53	 *
54	 * @param run The generation the press created.
55	 */
56	function useTheRun(run: TheRun): WhereItHasGot {
57	  return useSyncExternalStore(run.watch, run.now, run.now);
58	}
59	
60	/**
61	 * The state of the run, as the one word the strip puts in front of its
62	 * sentence.
63	 *
64	 * Six phases and seven words, because *live* and *replay* are the same phase
65	 * seen two ways and the difference matters to a reader: one is spending money
66	 * and taking a minute a call, the other is a recording being played back.
67	 *
68	 * @param phase Where the run has got to.
69	 * @param replaying True when this copy has no model key and is playing a
70	 *   recording back.
71	 */
72	export function theWordFor(phase: Phase, replaying: boolean): string {
73	  switch (phase) {
74	    case "waiting":
75	    case "growing":
76	      return replaying ? "replay" : "live";
77	    // A cap stopping a run and a run reaching its own end are both a finished
78	    // map: the map is on screen, nothing more is coming, and *why* is the
79	    // sentence beside the word rather than the word itself.
80	    case "settled":
81	    case "stopped":
82	      return "finished";
83	    case "failed":
84	      return "stopped";
85	    case "ended_early":
86	      return "ended early";
87	  }
88	}
89	
90	/** What the screen needs. */
91	export interface GenerationScreenProps {
92	  /** The run, already asked for by the press that opened this screen. */
93	  readonly run: TheRun;
94	  /**
95	   * True when this copy has no model key, so the run is a recording being played
96	   * back. Known before the stream says anything, which is why the badge can be
97	   * on screen from the first frame — and why the offer to run it again can say
98	   * truthfully whether pressing it spends money.
99	   */
100	  readonly replaying: boolean;
101	  /** Ask for the same sentence again. A press, like the first one. */
102	  readonly onRunAgain: () => void;
103	  /** Let go of this run and go back. A press, and the only way off this screen. */
104	  readonly onLeave: () => void;
105	}
106	
107	/** A map building itself, and the panel beside it. */
108	export function GenerationScreen({ run, replaying, onRunAgain, onLeave }: GenerationScreenProps) {
109	  const { growth, saying } = useTheRun(run);
110	  const [selection, setSelection] = useState<Selection>(null);
111	  const [focused, setFocused] = useState<string | null>(null);
112	  const [overlay, setOverlay] = useState<"sheet" | "palette" | null>(null);
113	  const [dock, setDock] = useState<"panel" | "outline">("panel");
114	  const [openAt, setOpenAt] = useState<number | null>(null);
115	  const [status, setStatus] = useState(
116	    "Press ? for every key. j and k walk a column; h and l follow the wires.",
117	  );
118	  const [working, setWorking] = useState<Working>({ state: "reading" });
119	
120	  const { generationId, phase } = growth;
121	  const finished = hasStopped(phase);
122	
123	  // **How many events have arrived**, so the strip at the foot knows when to
124	  // start counting the silence again.
125	  //
126	  // It counts the run's own state being replaced, which is one for one with an
127	  // event arriving: `fold` hands back a new state for every one of the eight
128	  // events — it says so in its own words, *there is no event this hands its
129	  // argument back for* — so a new object here is something having landed.
130	  //
131	  // **It is a count of arrivals and nothing else, and it is never drawn.**
132	  // The browser can count what it was sent; it cannot count the model's calls,
133	  // and must never print a number as if it could.
134	  const [arrivals, setArrivals] = useState(0);
135	  const lastSeen = useRef<Growth | null>(null);
136	  useEffect(() => {
137	    if (lastSeen.current === growth) {
138	      return;
139	    }
140	    lastSeen.current = growth;
141	    setArrivals((many) => many + 1);
142	  }, [growth]);
143	
144	  // The same three keys as every other screen, from the one module that binds
145	  // them — this screen prints *Press ? for every key* under the map, and until
146	  // that module existed the press did nothing here.
147	  useEveryKey({
148	    everyKey: () => setOverlay((was) => (was === "sheet" ? null : "sheet")),
149	    palette: () => setOverlay((was) => (was === "palette" ? null : "palette")),
150	    escape: () => setOverlay(null),
151	  });
152	
153	  // The working of the run, read once the run has finished. It is asked for then
154	  // rather than as it goes, because the server writes it from the same pass that
155	  // writes the stream and a half-read one would be a second, staler copy.
156	  //
157	  // **A run that ended early has a working too**, and it is the one case where
158	  // reading it back matters most: it is the only record of how far the run got.
159	  useEffect(() => {
160	    if (generationId === null || !finished) {
161	      return;
162	    }
163	    let stillWanted = true;
164	    readTranscript(generationId).then(
165	      (read) => {
166	        if (stillWanted) {
167	          setWorking(read);
168	        }
169	      },
170	      // `readTranscript` answers rather than throws, for every failure it can
171	      // name. This is for the ones it cannot: a screen that waits for a promise
172	      // that will never settle says *Reading the working…* until the tab closes.
173	      () => {
174	        if (stillWanted) {
175	          setWorking({
176	            state: "gone",
177	            reason: "The working of this run could not be read, and nothing said why.",
178	          });
179	        }
180	      },
181	    );
182	    return () => {
183	      stillWanted = false;
184	    };
185	  }, [generationId, finished]);
186	
187	  const outline = useMemo(() => outlineOf(growth.world), [growth.world]);
188	
189	  // The keyboard follows the growing edge: a claim that has just arrived takes
190	  // focus, exactly as a claim a branch adds does. That is what keeps the newest
191	  // tile on the glass through a run that goes on for minutes — the canvas
192	  // already brings whatever the keyboard is on into view, so nothing here
193	  // re-frames the map and nothing re-lays it out. A tile that is already placed
194	  // stays exactly where it is; what moves is where the reader is looking.
195	  //
196	  // A claim that has just **arrived** takes focus, and nothing else does. The
197	  // count is what says one arrived: when the likelihoods land, the engine's own
198	  // world replaces the drawing and its claims come back in the map's order
199	  // rather than the order they were proposed in — which is not an arrival, and
200	  // moving the view for it would slide the map sideways at the very moment it
201	  // stopped changing.
202	  const howManyClaims = growth.world.claims.length;
203	  const seenSoFar = useRef(0);
204	  const lastArrived = useRef<string | null>(null);
205	  useEffect(() => {
206	    if (howManyClaims <= seenSoFar.current) {
207	      return;
208	    }
209	    seenSoFar.current = howManyClaims;
210	    const arrived = growth.world.claims[howManyClaims - 1]?.id ?? null;
211	    lastArrived.current = arrived;
212	    setFocused(arrived);
213	  }, [howManyClaims, growth.world.claims]);
214	
215	  // And it lets go the moment the run stops. Focus is also what the hover lens
216	  // reads, and a lens left on a claim the machine chose would dim the whole
217	  // finished map to fifteen per cent at exactly the moment the reader starts
218	  // reading it. If the reader has moved since, their focus is theirs and stays.
219	  useEffect(() => {
220	    if (!finished) {
221	      return;
222	    }
223	    setFocused((was) => (was === lastArrived.current ? null : was));
224	  }, [finished]);
225	
226	  const pick = useCallback((id: string) => {
227	    setFocused(id);
228	    setSelection({ kind: "claim", id });
229	  }, []);
230	
231	  // Nothing on this screen is bound to the map's own six operations yet, so the
232	  // keys that open them say so rather than doing nothing.
233	  /**
234	   * Every command this screen has, by name.
235	   *
236	   * **It is a screen's own list, not a copy of the stored map's.** A generated
237	   * map has no branches to open and none of the six things you can do to a
238	   * claim, so offering them here would be a palette full of commands that
239	   * explain why they cannot run. What it does have is the four ways around it
240	   * and the two things it can do, and each one is also a key or a control on
241	   * the screen — which is the palette's whole promise.
242	   *
243	   * Before this, ⌘K on this screen opened the shortcuts sheet: a key that
244	   * silently does something else is the one thing this product's keyboard is
245	   * not allowed to do.
246	   */
247	  const commands: Command[] = useMemo(
248	    () => [
249	      {
250	        name: "Read the map as a list",
251	        does: "The same as pressing O. Every claim, one sentence each, in the order they arrived.",
252	        run: () => {
253	          setDock("outline");
254	          setStatus("the map as a list");
255	        },
256	      },
257	      {
258	        name: "Read the panel beside the map",
259	        does: "The same as pressing O again. What this run refused, what it cost, and why.",
260	        run: () => {
261	          setDock("panel");
262	          setStatus("the panel beside the map");
263	        },
264	      },
265	      // **Only once there is a working.** It is read back from the server when
266	      // the run stops, so a press before then leaves the panel saying *Reading
267	      // the working of this run…* until the run ends — a command that appears to
268	      // do nothing for two minutes.
269	      ...(generationId === null || !finished
270	        ? []
271	        : [
272	            {
273	              name: "Read the working of this run",
274	              does: "Every call it made, in order. The same as the control in the panel.",
275	              run: () => {
276	                setOpenAt(null);
277	                setDock("panel");
278	                setSelection({ kind: "generation", id: generationId });
279	              },
280	            },
281	          ]),
282	      {
283	        name: "Every key",
284	        does: "The sheet of every key on this map. The same as pressing ?.",
285	        run: () => setOverlay("sheet"),
286	      },
287	      {
288	        name: "Back to the launchpad",
289	        does: "Let this run go and start again. The same as the control at the top left.",
290	        run: onLeave,
291	      },
292	    ],
293	    [generationId, finished, onLeave],
294	  );
295	
296	  const keys: MapKeys = useMemo(
297	    () => ({
298	      intervene: () => setStatus("a generated map takes edits through Add a claim, beside the map"),
299	      branch: () => setStatus("a branch is started on a stored map; this one is still being built"),
300	      flipWorlds: () => setStatus("there is nothing to flip to — no branch is open"),
301	      outline: () =>
302	        setDock((was) => {
303	          const next = was === "outline" ? "panel" : "outline";
304	          setStatus(next === "outline" ? "the map as a list" : "the panel beside the map");
305	          return next;
306	        }),
307	      panel: () => setStatus("the panel is beside the map"),
308	      palette: () => setOverlay("palette"),
309	    }),
310	    [],
311	  );
312	
313	  return (
314	    <MapFrame
315	      title={growth.world.title}
316	      onLeave={onLeave}
317	      onEveryKey={() => setOverlay("sheet")}
318	      where={
319	        <p className="map-bar__where">
320	          {/* Nothing sits over the map: the mark that says this run is a
321	              recording is a badge up here, and the sentence explaining it is in
322	              the line under the map with every other sentence about where this
323	              map came from. */}
324	          {replaying ? (
325	            <ReplayBadge
326	              recordingDate={growth.receipt?.recording_date ?? null}
327	              receiptMode={growth.receipt?.mode ?? null}
328	            />
329	          ) : null}
330	          {run.asked.target === null ? "Explore" : "Verify"}
331	          <span className="map-bar__side">
332	            {run.asked.target === null ? "what your sentence would cause" : run.asked.target}
333	          </span>
334	        </p>
335	      }
336	      map={
337	        <MapCanvas
338	          world={growth.world}
339	          selection={selection}
340	          onSelect={setSelection}
341	          focused={focused}
342	          onFocused={setFocused}
343	          mapKey={generationId ?? "a run that has not started"}
344	          keys={keys}
345	          onStatus={setStatus}
346	          onOverflow={() => setStatus("every claim is in the list beside the map")}
347	          arriving={!finished}
348	          reserved={growth.skeletons}
349	          // Framed once when the first rectangle is drawn, and once more when
350	          // the run stops — the one moment nothing on the map is moving and the
351	          // reader is about to start reading it.
352	          frameAgainOn={finished ? "the run stopped" : undefined}
353	        />
354	      }
355	      overlay={
356	        <>
357	          {overlay === "palette" ? (
358	            <CommandPalette open={true} onClose={() => setOverlay(null)} commands={commands} />
359	          ) : null}
360	          {overlay === "sheet" ? (
361	            <ShortcutsSheet open={true} onClose={() => setOverlay(null)} />
362	          ) : null}
363	        </>
364	      }
365	      status={status}
366	      // The one strip that says what this run is doing: the state as a word,
367	      // the run's own sentence — said out loud and printed, one element so the
368	      // two cannot drift — and, only on a live run that is still open, how long
369	      // it has been since anything arrived.
370	      strip={
371	        <RunStrip
372	          word={theWordFor(phase, replaying)}
373	          saying={saying}
374	          // **A replay counts no seconds, and neither does a run that has
375	          // stopped.** A replay is paced by the server at six tenths of a
376	          // second an event, so the reading would reset twice a second and
377	          // would be measuring our own pacing rather than any wait.
378	          arrivals={replaying || finished ? null : arrivals}
379	          after={
380	            <DoneLine
381	              done={growth.done}
382	              failure={growth.failure}
383	              endedEarly={phase === "ended_early"}
384	              // The offer is made only where there is something to offer: a
385	              // stream that stopped without saying why. A run that finished has
386	              // its map on screen, and a button asking whether to spend it all
387	              // again would be a control looking for a reason to exist.
388	              runAgain={
389	                phase === "ended_early" ? { costsMoney: !replaying, go: onRunAgain } : undefined
390	              }
391	            />
392	          }
393	        />
394	      }
395	      panel={
396	        /* The map as a list, in place of the panel, exactly as it is on a
397	           stored map: press O for it, press O again for the panel. It grows as
398	           the map grows, in the same causal order, so a reader who never sees
399	           the canvas hears the map being built rather than a silence followed
400	           by a finished list. */
401	        dock === "outline" ? (
402	          <Outline items={outline} onPick={pick} focused={focused} />
403	        ) : (
404	          <>
405	            {/* The Verify door's answer, at the top, when a destination was named. */}
406	            {growth.verdict === null || run.asked.target === null ? null : (
407	              <VerdictCard
408	                verdict={growth.verdict}
409	                target={run.asked.target}
410	                world={growth.world}
411	                onSelect={pick}
412	              />
413	            )}
414	
415	            <RefusalStrip
416	              refusals={growth.refusals}
417	              finished={finished}
418	              openAt={openAt}
419	              onOpen={(at) => {
420	                setOpenAt(at);
421	                setSelection({ kind: "generation", id: generationId ?? "" });
422	              }}
423	            />
424	
425	            {growth.receipt === null ? null : <ReceiptStrip receipt={growth.receipt} />}
426	
427	            {/* **One way into the working that is always there.**
428	                The panel's view of the run used to be reachable only from a
429	                refusal row or from the receipt strip's link — so a run that
430	                refused nothing had one way in, and only at the end, and a run
431	                whose stream was cut had none at all. That last one is the worst
432	                of the three: the working is the only record of how far a cut
433	                run got, the screen fetches it for exactly that reason, and then
434	                offered the reader no way to read it.
435	
436	                **And it appears only once there is a working.** It used to be
437	                drawn from the run's first event, while the thing it opens is
438	                read back from the server only when the run stops — so pressing
439	                it during the two minutes a reader is most likely to press it
440	                left the panel saying *Reading the working of this run…* until
441	                the run ended. A control that cannot do what it says is worse
442	                than no control. */}
443	            {generationId === null || !finished ? null : (
444	              <section className="generation-working" aria-label="The working of this run">
445	                <button
446	                  className="generation-working__open"
447	                  type="button"
448	                  onClick={() => {
449	                    setOpenAt(null);
450	                    setDock("panel");
451	                    setSelection({ kind: "generation", id: generationId });
452	                  }}
453	                >
454	                  Read the working of this run <span aria-hidden="true">→</span>
455	                </button>
